    # Assuming background=9 based on the demos

    VISIT = set()

    def flood_fill(r, c):
        stack = [(r, c)]
        VISIT.add((r, c))
        while stack:
            cr, cc = stack.pop()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
