    for r in range(H):
        for c in range(W):
            if (r == 0 or r == H-1 or c == 0 or c == W-1):
                if grid[r][c] == 9:
                    flood_fill(r, c)

    # Find and fill enclosed background regions
    for r in range(H):
        for c in range(W):
